-- Historical design example; not the current Dreamsleeve contract.
-- See docs/CurrentStateRu.md and the README in this example directory.
-- MMO Chat v1 SQLite schema
-- Timestamps are stored as INTEGER Unix time in milliseconds (UTC).
-- IDs are stored as TEXT (UUID/ULID generated by the application).
-- Normalized names are computed by the application, not by SQLite.

PRAGMA foreign_keys = ON;

BEGIN;

CREATE TABLE IF NOT EXISTS players (
    player_id                TEXT PRIMARY KEY,
    current_nickname         TEXT NOT NULL,
    normalized_nickname      TEXT NOT NULL,
    created_at_ms            INTEGER NOT NULL,
    updated_at_ms            INTEGER NOT NULL,
    last_login_at_ms         INTEGER,
    is_deleted               INTEGER NOT NULL DEFAULT 0 CHECK (is_deleted IN (0, 1))
);

CREATE TABLE IF NOT EXISTS player_identities (
    identity_id              TEXT PRIMARY KEY,
    player_id                TEXT NOT NULL,
    public_key               BLOB NOT NULL,
    algorithm                TEXT NOT NULL,
    key_version              INTEGER NOT NULL CHECK (key_version >= 1),
    is_active                INTEGER NOT NULL DEFAULT 1 CHECK (is_active IN (0, 1)),
    created_at_ms            INTEGER NOT NULL,
    revoked_at_ms            INTEGER,
    revoked_reason           TEXT,
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS player_identity_rebinds (
    rebind_id                TEXT PRIMARY KEY,
    player_id                TEXT NOT NULL,
    old_identity_id          TEXT,
    new_identity_id          TEXT NOT NULL,
    performed_by_player_id   TEXT,
    note                     TEXT,
    created_at_ms            INTEGER NOT NULL,
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (old_identity_id) REFERENCES player_identities(identity_id),
    FOREIGN KEY (new_identity_id) REFERENCES player_identities(identity_id),
    FOREIGN KEY (performed_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS player_server_roles (
    player_id                TEXT NOT NULL,
    role                     INTEGER NOT NULL CHECK (role IN (0, 1, 2)),
    granted_by_player_id     TEXT,
    granted_at_ms            INTEGER NOT NULL,
    PRIMARY KEY (player_id, role),
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (granted_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS player_sessions (
    session_id               TEXT PRIMARY KEY,
    player_id                TEXT NOT NULL,
    resume_token_hash        BLOB NOT NULL UNIQUE,
    issued_at_ms             INTEGER NOT NULL,
    expires_at_ms            INTEGER NOT NULL,
    last_seen_at_ms          INTEGER NOT NULL,
    revoked_at_ms            INTEGER,
    remote_addr              TEXT,
    client_platform          TEXT,
    client_build             TEXT,
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS friend_requests (
    request_id               TEXT PRIMARY KEY,
    from_player_id           TEXT NOT NULL,
    to_player_id             TEXT NOT NULL,
    status                   INTEGER NOT NULL CHECK (status IN (0, 1, 2, 3, 4)),
    created_at_ms            INTEGER NOT NULL,
    responded_at_ms          INTEGER,
    note                     TEXT,
    CHECK (from_player_id <> to_player_id),
    FOREIGN KEY (from_player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (to_player_id) REFERENCES players(player_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS friendships (
    player_low_id            TEXT NOT NULL,
    player_high_id           TEXT NOT NULL,
    created_at_ms            INTEGER NOT NULL,
    created_by_request_id    TEXT,
    PRIMARY KEY (player_low_id, player_high_id),
    CHECK (player_low_id < player_high_id),
    FOREIGN KEY (player_low_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (player_high_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (created_by_request_id) REFERENCES friend_requests(request_id)
);

CREATE TABLE IF NOT EXISTS player_blocks (
    blocker_player_id        TEXT NOT NULL,
    blocked_player_id        TEXT NOT NULL,
    created_at_ms            INTEGER NOT NULL,
    reason                   TEXT,
    PRIMARY KEY (blocker_player_id, blocked_player_id),
    CHECK (blocker_player_id <> blocked_player_id),
    FOREIGN KEY (blocker_player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (blocked_player_id) REFERENCES players(player_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS parties (
    party_id                 TEXT PRIMARY KEY,
    leader_player_id         TEXT NOT NULL,
    status                   INTEGER NOT NULL CHECK (status IN (0, 1)),
    created_at_ms            INTEGER NOT NULL,
    disbanded_at_ms          INTEGER,
    disbanded_by_player_id   TEXT,
    FOREIGN KEY (leader_player_id) REFERENCES players(player_id),
    FOREIGN KEY (disbanded_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS party_members (
    party_id                 TEXT NOT NULL,
    player_id                TEXT NOT NULL,
    joined_at_ms             INTEGER NOT NULL,
    join_order               INTEGER NOT NULL CHECK (join_order >= 1),
    invited_by_player_id     TEXT,
    PRIMARY KEY (party_id, player_id),
    UNIQUE (player_id),
    FOREIGN KEY (party_id) REFERENCES parties(party_id) ON DELETE CASCADE,
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS party_invites (
    invite_id                TEXT PRIMARY KEY,
    party_id                 TEXT NOT NULL,
    invited_player_id        TEXT NOT NULL,
    invited_by_player_id     TEXT NOT NULL,
    status                   INTEGER NOT NULL CHECK (status IN (0, 1, 2, 3, 4)),
    created_at_ms            INTEGER NOT NULL,
    expires_at_ms            INTEGER NOT NULL,
    responded_at_ms          INTEGER,
    FOREIGN KEY (party_id) REFERENCES parties(party_id) ON DELETE CASCADE,
    FOREIGN KEY (invited_player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS guilds (
    guild_id                 TEXT PRIMARY KEY,
    name                     TEXT NOT NULL,
    normalized_name          TEXT NOT NULL,
    created_by_player_id     TEXT NOT NULL,
    created_at_ms            INTEGER NOT NULL,
    status                   INTEGER NOT NULL CHECK (status IN (0, 1)),
    disbanded_at_ms          INTEGER,
    FOREIGN KEY (created_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS guild_memberships (
    guild_id                 TEXT NOT NULL,
    player_id                TEXT NOT NULL,
    role                     INTEGER NOT NULL CHECK (role IN (0, 1, 2)),
    joined_at_ms             INTEGER NOT NULL,
    invited_by_player_id     TEXT,
    muted_until_ms           INTEGER,
    PRIMARY KEY (guild_id, player_id),
    FOREIGN KEY (guild_id) REFERENCES guilds(guild_id) ON DELETE CASCADE,
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS guild_invites (
    invite_id                TEXT PRIMARY KEY,
    guild_id                 TEXT NOT NULL,
    invited_player_id        TEXT NOT NULL,
    invited_by_player_id     TEXT NOT NULL,
    status                   INTEGER NOT NULL CHECK (status IN (0, 1, 2, 3, 4)),
    created_at_ms            INTEGER NOT NULL,
    expires_at_ms            INTEGER NOT NULL,
    responded_at_ms          INTEGER,
    FOREIGN KEY (guild_id) REFERENCES guilds(guild_id) ON DELETE CASCADE,
    FOREIGN KEY (invited_player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS global_sanctions (
    sanction_id              TEXT PRIMARY KEY,
    player_id                TEXT NOT NULL,
    sanction_type            INTEGER NOT NULL CHECK (sanction_type IN (0, 1)),
    issued_by_player_id      TEXT,
    reason                   TEXT,
    issued_at_ms             INTEGER NOT NULL,
    expires_at_ms            INTEGER,
    revoked_at_ms            INTEGER,
    revoked_by_player_id     TEXT,
    FOREIGN KEY (player_id) REFERENCES players(player_id) ON DELETE CASCADE,
    FOREIGN KEY (issued_by_player_id) REFERENCES players(player_id),
    FOREIGN KEY (revoked_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS text_filter_terms (
    term_id                  TEXT PRIMARY KEY,
    term                     TEXT NOT NULL,
    normalized_term          TEXT NOT NULL,
    mode                     INTEGER NOT NULL CHECK (mode IN (0, 1)),
    created_at_ms            INTEGER NOT NULL,
    created_by_player_id     TEXT,
    FOREIGN KEY (created_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS scheduled_announcements (
    announcement_id          TEXT PRIMARY KEY,
    channel_scope            INTEGER NOT NULL CHECK (channel_scope IN (0, 1)),
    is_enabled               INTEGER NOT NULL DEFAULT 1 CHECK (is_enabled IN (0, 1)),
    interval_seconds         INTEGER NOT NULL CHECK (interval_seconds >= 1),
    message_text             TEXT NOT NULL,
    created_at_ms            INTEGER NOT NULL,
    updated_at_ms            INTEGER NOT NULL,
    created_by_player_id     TEXT,
    FOREIGN KEY (created_by_player_id) REFERENCES players(player_id)
);

CREATE TABLE IF NOT EXISTS audit_events (
    audit_event_id           TEXT PRIMARY KEY,
    category                 INTEGER NOT NULL CHECK (category IN (0, 1, 2, 3, 4, 5)),
    actor_player_id          TEXT,
    subject_player_id        TEXT,
    guild_id                 TEXT,
    party_id                 TEXT,
    action_type              TEXT NOT NULL,
    description              TEXT,
    payload_text             TEXT,
    occurred_at_ms           INTEGER NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_players_created_at_ms
    ON players(created_at_ms);

CREATE UNIQUE INDEX IF NOT EXISTS ux_players_normalized_nickname_active
    ON players(normalized_nickname)
    WHERE is_deleted = 0;

CREATE UNIQUE INDEX IF NOT EXISTS ux_player_identities_active_per_player
    ON player_identities(player_id)
    WHERE is_active = 1;

CREATE INDEX IF NOT EXISTS ix_player_identities_player
    ON player_identities(player_id, key_version DESC);

CREATE INDEX IF NOT EXISTS ix_player_sessions_player
    ON player_sessions(player_id);

CREATE INDEX IF NOT EXISTS ix_player_sessions_expiry
    ON player_sessions(expires_at_ms, revoked_at_ms);

CREATE UNIQUE INDEX IF NOT EXISTS ux_friend_requests_pending_pair
    ON friend_requests(from_player_id, to_player_id)
    WHERE status = 0;

CREATE INDEX IF NOT EXISTS ix_friend_requests_to_status
    ON friend_requests(to_player_id, status, created_at_ms DESC);

CREATE INDEX IF NOT EXISTS ix_friendships_high
    ON friendships(player_high_id);

CREATE INDEX IF NOT EXISTS ix_player_blocks_blocked
    ON player_blocks(blocked_player_id);

CREATE INDEX IF NOT EXISTS ix_party_members_party_order
    ON party_members(party_id, join_order);

CREATE UNIQUE INDEX IF NOT EXISTS ux_party_invites_pending_target
    ON party_invites(party_id, invited_player_id)
    WHERE status = 0;

CREATE INDEX IF NOT EXISTS ix_party_invites_target_status
    ON party_invites(invited_player_id, status, created_at_ms DESC);

CREATE UNIQUE INDEX IF NOT EXISTS ux_guilds_normalized_name_active
    ON guilds(normalized_name)
    WHERE status = 0;

CREATE INDEX IF NOT EXISTS ix_guild_memberships_player
    ON guild_memberships(player_id, joined_at_ms DESC);

CREATE UNIQUE INDEX IF NOT EXISTS ux_guild_one_master
    ON guild_memberships(guild_id)
    WHERE role = 2;

CREATE UNIQUE INDEX IF NOT EXISTS ux_guild_invites_pending_target
    ON guild_invites(guild_id, invited_player_id)
    WHERE status = 0;

CREATE INDEX IF NOT EXISTS ix_guild_invites_target_status
    ON guild_invites(invited_player_id, status, created_at_ms DESC);

CREATE INDEX IF NOT EXISTS ix_global_sanctions_player
    ON global_sanctions(player_id, sanction_type, issued_at_ms DESC);

CREATE INDEX IF NOT EXISTS ix_text_filter_terms_mode
    ON text_filter_terms(mode);

CREATE UNIQUE INDEX IF NOT EXISTS ux_text_filter_terms_normalized
    ON text_filter_terms(normalized_term);

CREATE INDEX IF NOT EXISTS ix_scheduled_announcements_enabled
    ON scheduled_announcements(is_enabled);

CREATE INDEX IF NOT EXISTS ix_audit_events_occurred_at
    ON audit_events(occurred_at_ms DESC);

CREATE INDEX IF NOT EXISTS ix_audit_events_actor
    ON audit_events(actor_player_id, occurred_at_ms DESC);

CREATE INDEX IF NOT EXISTS ix_audit_events_subject
    ON audit_events(subject_player_id, occurred_at_ms DESC);

COMMIT;

-- Suggested enum meanings:
-- player_server_roles.role: 0=moderator, 1=gamemaster, 2=owner
-- friend_requests.status / party_invites.status / guild_invites.status:
--   0=pending, 1=accepted, 2=declined, 3=revoked_or_canceled, 4=expired
-- parties.status / guilds.status: 0=active, 1=disbanded
-- guild_memberships.role: 0=member, 1=officer, 2=guild_master
-- global_sanctions.sanction_type: 0=global_mute, 1=global_ban
-- text_filter_terms.mode: 0=block, 1=redact
-- scheduled_announcements.channel_scope: 0=system_feed, 1=global_chat
-- audit_events.category: 0=identity, 1=social, 2=party, 3=guild, 4=moderation, 5=admin
